#define _GNU_SOURCE
#include <z3.h>
#include <dlfcn.h>
#include <execinfo.h>
#include <errno.h>
#include <inttypes.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

typedef Z3_lbool (*check_fn)(Z3_context, Z3_solver);
typedef Z3_lbool (*assumptions_fn)(Z3_context, Z3_solver, unsigned, Z3_ast const[]);
static check_fn next_check;
static assumptions_fn next_assumptions;
static pthread_once_t resolve_once = PTHREAD_ONCE_INIT;
static _Thread_local unsigned call_depth;
static _Atomic uint64_t check_calls, assumptions_calls, outer_checks;
static _Atomic uint64_t sat_results, unsat_results, unknown_results;
static _Atomic uint64_t elapsed_ns, thread_cpu_ns, clock_failures, outer_entered;
static pthread_mutex_t publish_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;
static _Atomic int exiting;
static void publish_results(void);


struct clocks { struct timespec elapsed, cpu; int valid; };
static void dump_slow_query(Z3_context, Z3_solver, struct clocks);

static void resolve_symbols(void) {
    next_check = (check_fn)dlsym(RTLD_NEXT, "Z3_solver_check");
    next_assumptions = (assumptions_fn)dlsym(RTLD_NEXT, "Z3_solver_check_assumptions");
    if (!next_check || !next_assumptions) {
        fprintf(stderr, "z3-check-probe: cannot resolve native Z3 check functions\n");
        _exit(127);
    }
}

static struct clocks read_clocks(void) {
    struct clocks result = {0};
    result.valid = clock_gettime(CLOCK_MONOTONIC, &result.elapsed) == 0
        && clock_gettime(CLOCK_THREAD_CPUTIME_ID, &result.cpu) == 0;
    if (!result.valid) atomic_fetch_add_explicit(&clock_failures, 1, memory_order_relaxed);
    return result;
}

static uint64_t delta_ns(struct timespec before, struct timespec after) {
    int64_t seconds = (int64_t)after.tv_sec - (int64_t)before.tv_sec;
    int64_t nanoseconds = (int64_t)after.tv_nsec - (int64_t)before.tv_nsec;
    return (uint64_t)(seconds * INT64_C(1000000000) + nanoseconds);
}

static void record_result(Z3_lbool result, struct clocks before) {
    struct clocks after = read_clocks();
    pthread_mutex_lock(&stats_lock);
    atomic_fetch_add_explicit(&outer_checks, 1, memory_order_relaxed);
    if (result == Z3_L_TRUE) atomic_fetch_add_explicit(&sat_results, 1, memory_order_relaxed);
    else if (result == Z3_L_FALSE) atomic_fetch_add_explicit(&unsat_results, 1, memory_order_relaxed);
    else atomic_fetch_add_explicit(&unknown_results, 1, memory_order_relaxed);
    if (before.valid && after.valid) {
        atomic_fetch_add_explicit(&elapsed_ns, delta_ns(before.elapsed, after.elapsed), memory_order_relaxed);
        atomic_fetch_add_explicit(&thread_cpu_ns, delta_ns(before.cpu, after.cpu), memory_order_relaxed);
    }
    pthread_mutex_unlock(&stats_lock);
}

Z3_lbool Z3_solver_check(Z3_context context, Z3_solver solver) {
    int prior_errno = errno;
    pthread_once(&resolve_once, resolve_symbols);
    atomic_fetch_add_explicit(&check_calls, 1, memory_order_relaxed);
    int outer = call_depth++ == 0;
    struct clocks before = {0};
    if (outer) { pthread_mutex_lock(&stats_lock); atomic_fetch_add_explicit(&outer_entered, 1, memory_order_relaxed); pthread_mutex_unlock(&stats_lock); before = read_clocks(); }
    errno = prior_errno;
    Z3_lbool result = next_check(context, solver);
    int native_errno = errno;
    --call_depth;
    if (outer) { record_result(result, before); dump_slow_query(context, solver, before); publish_results(); }
    errno = native_errno;
    return result;
}

Z3_lbool Z3_solver_check_assumptions(Z3_context context, Z3_solver solver,
                                  unsigned count, Z3_ast const assumptions[]) {
    int prior_errno = errno;
    pthread_once(&resolve_once, resolve_symbols);
    atomic_fetch_add_explicit(&assumptions_calls, 1, memory_order_relaxed);
    int outer = call_depth++ == 0;
    struct clocks before = {0};
    if (outer) { pthread_mutex_lock(&stats_lock); atomic_fetch_add_explicit(&outer_entered, 1, memory_order_relaxed); pthread_mutex_unlock(&stats_lock); before = read_clocks(); }
    errno = prior_errno;
    Z3_lbool result = next_assumptions(context, solver, count, assumptions);
    int native_errno = errno;
    --call_depth;
    if (outer) { record_result(result, before); dump_slow_query(context, solver, before); publish_results(); }
    errno = native_errno;
    return result;
}

static void publish_results(void) {
    const char *path = getenv("EVM_Z3_CHECK_PROBE_OUTPUT");
    if (!path || !*path) return;
    pthread_mutex_lock(&publish_lock);
    size_t length = strlen(path) + 32;
    char *temporary = malloc(length);
    if (!temporary) { pthread_mutex_unlock(&publish_lock); return; }
    snprintf(temporary, length, "%s.tmp.%ld", path, (long)getpid());
    FILE *output = fopen(temporary, "w");
    if (!output) {
        fprintf(stderr, "z3-check-probe: cannot open output %s\n", path);
        free(temporary); pthread_mutex_unlock(&publish_lock); return;
    }
    pthread_mutex_lock(&stats_lock);
    uint64_t completed = atomic_load_explicit(&outer_checks, memory_order_relaxed);
    uint64_t entered = atomic_load_explicit(&outer_entered, memory_order_relaxed);
    struct timespec observed = {0};
    clock_gettime(CLOCK_MONOTONIC, &observed);
    fprintf(output, "{\"outer_entered\":%" PRIu64 ",\"in_flight_outer_checks\":%" PRIu64 ",\"snapshot_monotonic_ns\":%" PRIu64 ",\"normal_exit_snapshot\":%s,", entered, entered - completed, (uint64_t)observed.tv_sec * UINT64_C(1000000000) + observed.tv_nsec, atomic_load(&exiting) ? "true" : "false");
    fprintf(output,
        "\"schema\":\"z3-check-live-probe-v1\",\"pid\":%ld,"
        "\"check_calls\":%" PRIu64 ",\"check_assumptions_calls\":%" PRIu64 ","
        "\"outer_checks\":%" PRIu64 ",\"sat\":%" PRIu64 ",\"unsat\":%" PRIu64 ",\"unknown\":%" PRIu64 ","
        "\"elapsed_ns\":%" PRIu64 ",\"thread_cpu_ns\":%" PRIu64 ",\"clock_failures\":%" PRIu64 "}\n",
        (long)getpid(),
        atomic_load_explicit(&check_calls, memory_order_relaxed),
        atomic_load_explicit(&assumptions_calls, memory_order_relaxed),
        atomic_load_explicit(&outer_checks, memory_order_relaxed),
        atomic_load_explicit(&sat_results, memory_order_relaxed),
        atomic_load_explicit(&unsat_results, memory_order_relaxed),
        atomic_load_explicit(&unknown_results, memory_order_relaxed),
        atomic_load_explicit(&elapsed_ns, memory_order_relaxed),
        atomic_load_explicit(&thread_cpu_ns, memory_order_relaxed),
        atomic_load_explicit(&clock_failures, memory_order_relaxed));
    pthread_mutex_unlock(&stats_lock);
    if (fclose(output) != 0) fprintf(stderr, "z3-check-probe: output close failed\n");
    else if (rename(temporary, path) != 0) fprintf(stderr, "z3-check-probe: atomic publish failed\n");
    free(temporary);
    pthread_mutex_unlock(&publish_lock);
}

/* Periodic and per-completed-check publishing survive SIGTERM. Cost sums
 * cover completed native calls only; a cancelled/in-flight call is excluded.
 * Statistics are captured under a mutex. Final normal-exit statistics are
 * exact after all checks have returned; periodic interrupted costs are lower bounds. */
static void *sample_live(void *unused) {
    (void)unused;
    while (!atomic_load(&exiting)) {
        struct timespec delay = {.tv_sec = 1, .tv_nsec = 0};
        nanosleep(&delay, NULL);
        if (!atomic_load(&exiting)) publish_results();
    }
    return NULL;
}
__attribute__((constructor)) static void start_live(void) {
    const char *path = getenv("EVM_Z3_CHECK_PROBE_OUTPUT");
    if (!path || !*path) return;
    publish_results();
    pthread_t sampler;
    if (pthread_create(&sampler, NULL, sample_live, NULL) == 0) pthread_detach(sampler);
}
__attribute__((destructor)) static void finish_live(void) {
    atomic_store(&exiting, 1);
    publish_results();
}

/* Optional diagnostic-only export after the native check returned, on its
 * owning thread while its context/solver still exist. It does not run from
 * the sampler or signal handler. Max8 slow checks, max512KiB/file. */
static void dump_slow_query(Z3_context context, Z3_solver solver, struct clocks before) {
    const char *prefix = getenv("EVM_Z3_SLOW_QUERY_PREFIX");
    if (!prefix || !*prefix || !before.valid) return;
    struct timespec observed;
    if (clock_gettime(CLOCK_MONOTONIC, &observed) != 0 || delta_ns(before.elapsed, observed) < UINT64_C(200000000)) return;
    static _Atomic unsigned dumps;
    unsigned index = atomic_fetch_add(&dumps, 1);
    if (index >= 8) return;
    typedef const char *(*string_fn)(Z3_context, Z3_solver);
    string_fn to_string = (string_fn)dlsym(RTLD_NEXT, "Z3_solver_to_string");
    if (!to_string) return;
    const char *formula = to_string(context, solver);
    if (!formula) return;
    char path[4096];
    if (snprintf(path, sizeof(path), "%s-%ld-%u.smt2", prefix, (long)getpid(), index) >= (int)sizeof(path)) return;
    FILE *output = fopen(path, "w");
    if (!output) return;
    size_t bytes = strnlen(formula, 512 * 1024 + 1);
    fprintf(output, "; diagnostic: completed native check >=200ms; prefix capture; truncated=%s\n", bytes > 512 * 1024 ? "true" : "false");
    fwrite(formula, 1, bytes > 512 * 1024 ? 512 * 1024 : bytes, output);
    fclose(output);
    snprintf(path, sizeof(path), "%s-%ld-%u.moduli-and-stack.txt", prefix, (long)getpid(), index);
    output = fopen(path, "w");
    if (!output) return;
    const char *cursor = formula;
    for (unsigned occurrence = 0; occurrence < 16; ++occurrence) {
        const char *found = strstr(cursor, "bvurem");
        if (!found) break;
        fprintf(output, "urem_fragment%u: %.256s\n", occurrence, found);
        cursor = found + 6;
    }
    fflush(output);
    void *frames[80];
    int count = backtrace(frames, 80);
    backtrace_symbols_fd(frames, count, fileno(output));
    fclose(output);
}

probe_verification.smoke_source:
#include <z3.h>

int main(void) {
    Z3_config config = Z3_mk_config();
    Z3_context context = Z3_mk_context(config);
    Z3_del_config(config);
    Z3_solver solver = Z3_mk_solver(context);
    Z3_solver_inc_ref(context, solver);
    Z3_lbool first = Z3_solver_check(context, solver);
    Z3_ast no = Z3_mk_false(context);
    Z3_lbool second = Z3_solver_check_assumptions(context, solver, 1, &no);
    Z3_solver_dec_ref(context, solver);
    Z3_del_context(context);
    return first == Z3_L_TRUE && second == Z3_L_FALSE ? 0 : 1;
}

